/**
 * The shape of an advisory AI pre-review, and parsing it from
 * `GET /v1/papers/{id}/ai-reviews` (feature 122's endpoint).
 *
 * A report is one node-signed record (feature 121) served as JSON:
 *
 * ```json
 * {
 *   "paper": "sch:k3f9-q2xz-7mwd", "version": 2, "reviewCid": "bafy…",
 *   "advisory": true, "label": "Advisory. Generated by AI agents. Not a peer review.",
 *   "models": [{"name": "…", "version": "…", "provider": "…"}],
 *   "promptSetHash": "64 hex chars",
 *   "agents": [{"agent": "methodology", "findings": [ … ]}],
 *   "rebuttals": [ … ], "assessments": [ … ]
 * }
 * ```
 *
 * A finding names its agent, states one problem (`claim`), rates it
 * (`severity` info→critical, `confidence` low→high) and rests on exactly one
 * piece of evidence — a span quoted from the paper (with the optional
 * `paragraph_id` of the block it was copied from), a `reference_id`, or a
 * `log_line` of the code-run sandbox (`apps/api/.../ai_review/findings.py`).
 * The meta-reviewer may add `also_reported_by`, `agents_disagree` and
 * `needs_human_check` (feature 120). Authors answer a finding with a rebuttal
 * and tier-3 reviewers mark it confirmed or wrong (feature 123); both travel
 * with their finding here.
 *
 * Parsing is tolerant on purpose. The endpoint is versioned and may grow
 * fields, and a half-built node may serve fewer of them, so this module reads
 * the spellings the API already sends (`reviewCid` and `review_cid`, …),
 * keeps what it recognises and never throws: a report that reaches the tab is
 * shown, not rejected, and whatever cannot be understood degrades to a
 * neutral label rather than a blank panel.
 */

/** The banner every AI report carries, spelled as docs/design.md §8 spells it. */
export const ADVISORY_BANNER = "Advisory. Generated by AI agents. Not a peer review.";

/** The four specialist agents, in the order the pipeline lists them. */
export const AGENT_ORDER: readonly string[] = [
  "methodology",
  "literature",
  "reproducibility",
  "integrity",
];

/** How much a problem weakens the paper, least to most. */
export const SEVERITIES: readonly string[] = ["info", "minor", "major", "critical"];

/** How sure the agent is that the problem is real, least to most. */
export const CONFIDENCES: readonly string[] = ["low", "medium", "high"];

/** The kinds of evidence a finding may rest on, exactly one per finding. */
export type AiEvidenceKind = "span" | "reference_id" | "log_line";

/** What a finding rests on. */
export interface AiEvidence {
  /** Which of the three kinds this evidence is. */
  readonly kind: AiEvidenceKind;
  /** The quoted span, reference id (`ref:3`) or sandbox log line. */
  readonly value: string | null;
  /** The paragraph block a span was copied from, when the agent named it. */
  readonly paragraphId: string | null;
}

/** Evidence that names nothing recognised: shown, never dropped silently. */
export const UNKNOWN_EVIDENCE: AiEvidence = {
  kind: "span",
  value: null,
  paragraphId: null,
};

/** An author's answer to a finding (feature 123). */
export interface AiRebuttal {
  /** Stable key for list rendering. */
  readonly id: string;
  /** The finding this answers, as the API spells it. */
  readonly findingId: string;
  /** The author's DID, when the API names them. */
  readonly authorDid: string | null;
  readonly text: string;
  readonly createdAt: string | null;
}

/** A tier-3 reviewer's verdict on a finding (feature 123). */
export type AiVerdict = "confirmed" | "wrong";

/** A reviewer's verdict that a finding is real, or that it is not. */
export interface AiAssessment {
  /** Stable key for list rendering. */
  readonly id: string;
  readonly findingId: string;
  readonly reviewerDid: string | null;
  readonly verdict: AiVerdict;
  readonly createdAt: string | null;
}

/** One problem one agent reported. */
export interface AiFinding {
  /** The finding's id, as the rebuttal and assessment endpoints spell it. */
  readonly id: string;
  /** The agent that reported it (`agent`), never read from the model's reply. */
  readonly agent: string;
  /** One sentence stating the problem. */
  readonly claim: string;
  /** One of {@link SEVERITIES}, or an unknown word shown as it arrives. */
  readonly severity: string;
  /** One of {@link CONFIDENCES}, or an unknown word shown as it arrives. */
  readonly confidence: string;
  readonly evidence: AiEvidence;
  /** Other agents the meta-reviewer merged into this same finding. */
  readonly alsoReportedBy: readonly string[];
  /** The merged agents rated this finding differently (severity or confidence). */
  readonly agentsDisagree: boolean;
  /** An integrity observation that wants a person to look at it. */
  readonly needsHumanCheck: boolean;
  /** Authors' answers, oldest first. */
  readonly rebuttals: readonly AiRebuttal[];
  /** Reviewers' verdicts, oldest first. */
  readonly assessments: readonly AiAssessment[];
}

/** One agent's slice of a report; a specialist with nothing to say is listed too. */
export interface AiAgentGroup {
  /** The agent's name as the API spells it (the group key). */
  readonly agent: string;
  /** The display title: `Methodology`, `Literature`, …. */
  readonly title: string;
  readonly findings: readonly AiFinding[];
}

/** A model one of the agents ran on, with its version. */
export interface AiModel {
  readonly name: string | null;
  readonly version: string | null;
  readonly provider: string | null;
}

/** A paper's advisory AI pre-review, ready to show. */
export interface AiReport {
  /** The paper's `sch:` id, when the response names it. */
  readonly paperId: string | null;
  /** The version the report describes, when the response names it. */
  readonly version: number | null;
  /** The `ai.review` record's id; what rebuttals and assessments are posted to. */
  readonly reviewCid: string;
  /** Always true from this endpoint; the report is advisory, never a verdict. */
  readonly advisory: true;
  /** sha256 of the public prompt set, so a run can be reproduced. */
  readonly promptSetHash: string | null;
  readonly models: readonly AiModel[];
  /** One group per agent, specialists in pipeline order, then anyone else. */
  readonly agents: readonly AiAgentGroup[];
}

// --------------------------------------------------------------------------- //
// Reading values the API may spell in more than one way
// --------------------------------------------------------------------------- //

type Dict = Record<string, unknown>;

function isDict(value: unknown): value is Dict {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function text(value: unknown): string | null {
  return typeof value === "string" && value.trim() !== "" ? value : null;
}

/** The first present, non-empty string among the keys, else `null`. */
function pick(source: Dict, keys: readonly string[]): string | null {
  for (const key of keys) {
    const found = text(source[key]);
    if (found !== null) {
      return found;
    }
  }
  return null;
}

function count(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }
  if (typeof value === "string" && value.trim() !== "" && Number.isFinite(Number(value))) {
    return Number(value);
  }
  return null;
}

function flag(value: unknown): boolean {
  return value === true || value === "true";
}

function lower(value: unknown): string | null {
  const raw = text(value);
  return raw === null ? null : raw.trim().toLowerCase();
}

function listOf(value: unknown): readonly unknown[] {
  return Array.isArray(value) ? value : [];
}

/** A stable key for anything the API gave an id (or that fell back to its index). */
function keyOf(prefix: string, id: string | number): string {
  return `${prefix}:${id}`;
}

// --------------------------------------------------------------------------- //
// Findings
// --------------------------------------------------------------------------- //

/** A finding's id as the endpoints spell it: `finding_id` in any casing, or `id`. */
export function findingIdOf(raw: Dict, index: number): string {
  const id = pick(raw, ["finding_id", "findingId", "findingID", "id"]);
  return id ?? String(index);
}

function parseEvidence(raw: unknown): AiEvidence {
  if (!isDict(raw)) {
    return UNKNOWN_EVIDENCE;
  }
  const span = pick(raw, ["span"]);
  if (span !== null) {
    return {
      kind: "span",
      value: span,
      paragraphId: pick(raw, ["paragraph_id", "paragraphId"]),
    };
  }
  const reference = pick(raw, ["reference_id", "referenceId"]);
  if (reference !== null) {
    return { kind: "reference_id", value: reference, paragraphId: null };
  }
  const logLine = pick(raw, ["log_line", "logLine"]);
  if (logLine !== null) {
    return { kind: "log_line", value: logLine, paragraphId: null };
  }
  return UNKNOWN_EVIDENCE;
}

function parseRebuttal(raw: unknown, fallbackId: string): AiRebuttal | null {
  if (!isDict(raw)) {
    return null;
  }
  const words = pick(raw, ["text", "rebuttal", "response", "body"]);
  if (words === null) {
    return null;
  }
  return {
    id: keyOf("rebuttal", pick(raw, ["id", "rebuttal_id", "rebuttalId"]) ?? fallbackId),
    findingId: pick(raw, ["finding_id", "findingId", "findingID"]) ?? "",
    authorDid: pick(raw, ["author_did", "author", "authorDid"]),
    text: words,
    createdAt: pick(raw, ["created_at", "createdAt"]),
  };
}

/** The verdict spellings the endpoint already sends, and their plain words. */
export function parseVerdict(raw: unknown): AiVerdict | null {
  if (raw === true || raw === "confirmed" || raw === "Confirmed") {
    return "confirmed";
  }
  if (raw === "wrong") {
    return "wrong";
  }
  const word = lower(raw);
  if (word === null) {
    return null;
  }
  if (word.includes("confirm")) {
    return "confirmed";
  }
  if (word.includes("wrong") || word.includes("incorrect") || word.includes("false")) {
    return "wrong";
  }
  return null;
}

function parseAssessment(raw: unknown, fallbackId: string): AiAssessment | null {
  if (!isDict(raw)) {
    return null;
  }
  const verdict =
    parseVerdict(raw.verdict) ??
    parseVerdict(raw.status) ??
    parseVerdict(raw.assessment) ??
    parseVerdict(raw.result) ??
    (flag(raw.confirmed) ? "confirmed" : null) ??
    (flag(raw.wrong) ? "wrong" : null);
  if (verdict === null) {
    return null;
  }
  return {
    id: keyOf("assessment", pick(raw, ["id", "assessment_id", "assessmentId"]) ?? fallbackId),
    findingId: pick(raw, ["finding_id", "findingId", "findingID"]) ?? "",
    reviewerDid: pick(raw, ["reviewer_did", "reviewer", "reviewerDid"]),
    verdict,
    createdAt: pick(raw, ["created_at", "createdAt"]),
  };
}

function parseFinding(raw: unknown, index: number, groupAgent: string | null): AiFinding | null {
  if (!isDict(raw)) {
    return null;
  }
  const claim = pick(raw, ["claim", "text", "summary"]);
  const agent = pick(raw, ["agent", "agent_name", "agentName"]) ?? groupAgent ?? "report";
  if (claim === null) {
    return null;
  }
  return {
    id: findingIdOf(raw, index),
    agent,
    claim,
    severity: lower(raw.severity) ?? "info",
    confidence: lower(raw.confidence) ?? "low",
    evidence: parseEvidence(raw.evidence),
    alsoReportedBy: listOf(raw.also_reported_by ?? raw.alsoReportedBy).filter(
      (name): name is string => typeof name === "string" && name.trim() !== "",
    ),
    agentsDisagree: flag(raw.agents_disagree ?? raw.agentsDisagree),
    needsHumanCheck: flag(raw.needs_human_check ?? raw.needsHumanCheck),
    rebuttals: [],
    assessments: [],
  };
}

// --------------------------------------------------------------------------- //
// Responses, matched to their findings
// --------------------------------------------------------------------------- //

/**
 * Every rebuttal in the payload, taken from the top-level list the endpoint
 * sends (it re-lists there the responses it also attaches to findings, so
 * reading one place is enough and never double-counts).
 */
function collectRebuttals(payload: Dict): AiRebuttal[] {
  const collected = new Map<string, AiRebuttal>();
  listOf(payload.rebuttals).forEach((entry, index) => {
    const rebuttal = parseRebuttal(entry, String(index));
    if (rebuttal !== null) {
      collected.set(rebuttal.id, rebuttal);
    }
  });
  return [...collected.values()].sort((a, b) =>
    a.id.localeCompare(b.id, undefined, { numeric: true }),
  );
}

/** Every assessment in the payload, de-duplicated the same way. */
function collectAssessments(payload: Dict): AiAssessment[] {
  const collected = new Map<string, AiAssessment>();
  listOf(payload.assessments).forEach((entry, index) => {
    const assessment = parseAssessment(entry, String(index));
    if (assessment !== null) {
      collected.set(assessment.id, assessment);
    }
  });
  return [...collected.values()].sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
}

function attachResponses(
  findings: readonly AiFinding[],
  rebuttals: readonly AiRebuttal[],
  assessments: readonly AiAssessment[],
): readonly AiFinding[] {
  return findings.map((finding) => ({
    ...finding,
    rebuttals: rebuttals.filter((entry) => entry.findingId === finding.id),
    assessments: assessments.filter((entry) => entry.findingId === finding.id),
  }));
}

// --------------------------------------------------------------------------- //
// Groups and the report
// --------------------------------------------------------------------------- //

/** `methodology` → `Methodology`; an unknown agent keeps its own spelling. */
export function agentTitle(agent: string): string {
  return agent.charAt(0).toUpperCase() + agent.slice(1);
}

/** Groups sorted: the four specialists in pipeline order, then anyone else in arrival order. */
export function sortAgentGroups(groups: readonly AiAgentGroup[]): readonly AiAgentGroup[] {
  const rank = (agent: string): number => {
    const index = AGENT_ORDER.indexOf(agent);
    return index === -1 ? AGENT_ORDER.length : index;
  };
  return [...groups].sort((a, b) => rank(a.agent) - rank(b.agent));
}

/** An agent name flattened for matching: the API spells them in both cases. */
function agentKey(agent: string): string {
  return agent.trim().toLowerCase();
}

/**
 * Make the panels agree with "Also reported by".
 *
 * The meta-reviewer merges a finding into the agents that reported it
 * (`also_reported_by`), but the endpoint still lists it only in its primary
 * agent's group. Left alone, a finding could say "Also reported by Literature"
 * above a Literature panel that says "No findings". Each participating agent
 * therefore gets a copy of the finding in its own panel, and each copy's
 * "Also reported by" names the *other* participating panels — never itself,
 * and never an agent the report has no panel for (which could not show the
 * finding it is credited with).
 */
function shareCoReportedFindings(
  groups: readonly AiAgentGroup[],
): readonly AiAgentGroup[] {
  const canonical = new Map<string, string>();
  for (const group of groups) {
    const key = agentKey(group.agent);
    if (key !== "" && !canonical.has(key)) {
      canonical.set(key, group.agent);
    }
  }

  // Every finding, in panel order, with the panels that should show it.
  const participants = new Map<AiFinding, string[]>();
  const order: AiFinding[] = [];
  for (const group of groups) {
    for (const finding of group.findings) {
      const seen = participants.get(finding);
      if (seen === undefined) {
        participants.set(finding, [group.agent]);
        order.push(finding);
      } else if (!seen.includes(group.agent)) {
        seen.push(group.agent);
      }
    }
  }
  for (const finding of order) {
    const agents = participants.get(finding)!;
    for (const name of finding.alsoReportedBy) {
      const found = canonical.get(agentKey(name));
      if (found !== undefined && !agents.includes(found)) {
        agents.push(found);
      }
    }
  }

  return groups.map((group) => {
    const ownKey = agentKey(group.agent);
    const findings: AiFinding[] = [];
    for (const finding of order) {
      const agents = participants.get(finding)!;
      if (!agents.some((agent) => agentKey(agent) === ownKey)) {
        continue;
      }
      // A finding already in this panel stays once.
      if (
        findings.some(
          (seen) => seen.id === finding.id && seen.claim === finding.claim,
        )
      ) {
        continue;
      }
      findings.push({
        ...finding,
        agent: group.agent,
        alsoReportedBy: agents.filter((agent) => agentKey(agent) !== ownKey),
      });
    }
    return { ...group, findings };
  });
}

function parseGroups(payload: Dict): readonly AiAgentGroup[] {
  const groups: AiAgentGroup[] = [];

  for (const raw of listOf(payload.agents)) {
    if (!isDict(raw)) {
      continue;
    }
    const agent = pick(raw, ["agent", "name"]) ?? "report";
    const findings = listOf(raw.findings)
      .map((entry, index) => parseFinding(entry, index + 1, agent))
      .filter((finding): finding is AiFinding => finding !== null);
    groups.push({ agent, title: agentTitle(agent), findings });
  }

  if (groups.length === 0) {
    // No grouped layout: keep a flat findings list readable rather than blank.
    const findings = listOf(payload.findings)
      .map((entry, index) => parseFinding(entry, index + 1, null))
      .filter((finding): finding is AiFinding => finding !== null);
    if (findings.length > 0) {
      const byAgent = new Map<string, AiFinding[]>();
      for (const finding of findings) {
        const list = byAgent.get(finding.agent) ?? [];
        list.push(finding);
        byAgent.set(finding.agent, list);
      }
      for (const [agent, list] of byAgent) {
        groups.push({ agent, title: agentTitle(agent), findings: list });
      }
    }
  }

  return sortAgentGroups(shareCoReportedFindings(groups));
}

function parseModels(raw: unknown): readonly AiModel[] {
  return listOf(raw)
    .map((entry): AiModel | null => {
      if (typeof entry === "string") {
        return { name: entry, version: entry, provider: null };
      }
      if (!isDict(entry)) {
        return null;
      }
      return {
        name: pick(entry, ["name", "model"]),
        version: pick(entry, ["version", "model_version", "modelVersion"]),
        provider: pick(entry, ["provider"]),
      };
    })
    .filter((model): model is AiModel => model !== null);
}

/**
 * Parse the endpoint's response into an {@link AiReport}.
 *
 * Never throws: whatever the shape, the caller gets a report it can show. An
 * empty response yields a report with no groups — the tab's empty state.
 */
export function parseAiReport(payload: unknown): AiReport {
  const source: Dict = isDict(payload) ? payload : {};
  const groups = parseGroups(source);
  const rebuttals = collectRebuttals(source);
  const assessments = collectAssessments(source);

  return {
    paperId: pick(source, ["paper", "shortId", "short_id"]),
    version: count(source.version ?? source.n),
    reviewCid: pick(source, ["reviewCid", "review_cid"]) ?? "",
    advisory: true,
    promptSetHash: pick(source, ["promptSetHash", "prompt_set_hash"]),
    models: parseModels(source.models),
    agents: groups.map((group) => ({
      ...group,
      findings: attachResponses(group.findings, rebuttals, assessments),
    })),
  };
}

/**
 * How many distinct findings a report holds.
 *
 * A finding co-reported by several agents appears in each of their panels, so
 * the panels' counts are summed only after the copies are folded together;
 * the summary says how many problems the report found, not how many cards it
 * draws.
 */
export function findingCount(report: AiReport): number {
  const distinct = new Set<string>();
  for (const group of report.agents) {
    for (const finding of group.findings) {
      distinct.add(`${finding.id}\u0000${finding.claim}`);
    }
  }
  return distinct.size;
}

/** `No findings` · `1 finding` · `4 findings`. */
export function findingCountLabel(total: number): string {
  if (total === 0) {
    return "No findings";
  }
  return `${total} ${total === 1 ? "finding" : "findings"}`;
}

/** The severity word as it is shown: `major` → `Major`. */
export function severityLabel(severity: string): string {
  return severity.charAt(0).toUpperCase() + severity.slice(1);
}

/** The confidence phrase as it is shown: `medium` → `Confidence: medium`. */
export function confidenceLabel(confidence: string): string {
  return `Confidence: ${confidence}`;
}

/** What to call a piece of evidence: quoted from the paper, a reference, or the run log. */
export function evidenceLabel(evidence: AiEvidence): string {
  switch (evidence.kind) {
    case "span":
      return "Quoted from the paper";
    case "reference_id":
      return "Reference";
    case "log_line":
      return "Code run log";
  }
}

/**
 * Where the evidence link jumps to: the anchor of the paragraph the span was
 * copied from. The reading column gives each paragraph `id="p-{paragraph_id}"`,
 * so the link works wherever the tab is mounted beside the paper; without a
 * paragraph id there is nowhere to jump and the evidence is shown as plain
 * text instead of a dead link.
 */
export function evidenceAnchor(evidence: AiEvidence): string | null {
  return evidence.kind === "span" && evidence.paragraphId !== null
    ? `#p-${evidence.paragraphId}`
    : null;
}

/** The verdict's words: `Confirmed by a reviewer` / `Marked wrong by a reviewer`. */
export function verdictLabel(verdict: AiVerdict): string {
  return verdict === "confirmed" ? "Confirmed by a reviewer" : "Marked wrong by a reviewer";
}
